(function () {
  'use strict';

  var STORAGE_KEY = 'todos-vanilla-js';
  var uid = 0;

  /**
   * @planks-provisional("features/app-initialization.feature:TodoApp constructor initializes the application on instantiation")
   */
  function TodoApp() {
    this.todos = [];
    this.filter = 'all';
    this.editingId = null;
    this._editCancelled = false;
    this.init();
  }

  /**
   * @planks-provisional("features/app-initialization.feature:TodoApp constructor initializes the application on instantiation")
   */
  TodoApp.prototype.init = function () {
    this.load();
    this.render();
    this.bindEvents();
    this.handleRoute();
  };

  /**
   * @planks("the page has stored two todos in localStorage")
   * @planks("localStorage key {string} contains a todo with title {string} and completed true")
   */
  TodoApp.prototype.load = function () {
    try {
      this.todos = JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
    } catch (e) {
      this.todos = [];
    }
  };

  /**
   * @planks("localStorage key {string} contains a todo with title {string} and completed true")
   */
  TodoApp.prototype.save = function () {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(this.todos));
  };

  /**
   * @planks("{string} is added to the todo list")
   */
  TodoApp.prototype.addTodo = function (title) {
    title = title.trim();
    if (!title) return;
    this.todos.push({ id: ++uid, title: title, completed: false });
    this.save();
    this.render();
  };

  /**
   * @planks("{string} is removed from the todo list")
   */
  TodoApp.prototype.destroyTodo = function (id) {
    this.todos = this.todos.filter(function (t) { return t.id !== id; });
    this.editingId = null;
    this.save();
    this.render();
  };

  /**
   * @planks("{string} has the class {string}")
   */
  TodoApp.prototype.toggleTodo = function (id) {
    var todo = this.todos.find(function (t) { return t.id === id; });
    if (todo) {
      todo.completed = !todo.completed;
      this.save();
      this._updateTodoListItem(id);
      this.renderCounter();
      this.renderToggleAll();
      this.renderClearCompleted();
    }
  };

  /**
   * @planks("the todo title is updated to {string}")
   * @planks("{string} is removed from the todo list")
   */
  TodoApp.prototype.editTodo = function (id, title) {
    title = title.trim();
    if (!title) {
      this.destroyTodo(id);
      return;
    }
    var todo = this.todos.find(function (t) { return t.id === id; });
    if (todo) {
      todo.title = title;
      this.save();
    }
    this.editingId = null;
    this.render();
  };

  /**
   * @planks("the clear completed button is hidden")
   * @planks("{string} is removed from the todo list")
   */
  TodoApp.prototype.clearCompleted = function () {
    this.todos = this.todos.filter(function (t) { return !t.completed; });
    this.save();
    this.render();
  };

  /**
   * @planks("all todos are marked as complete")
   * @planks("all todos are marked as active")
   */
  TodoApp.prototype.toggleAll = function (checked) {
    var self = this;
    this.todos.forEach(function (t) { t.completed = checked; });
    this.save();
    this._updateAllTodoListItems();
    this.renderCounter();
    this.renderClearCompleted();
  };

  TodoApp.prototype._updateTodoListItem = function (id) {
    var self = this;
    var li = document.querySelector('.todo-list li[data-id="' + id + '"]');
    if (!li) return;
    var todo = this.todos.find(function (t) { return t.id === id; });
    if (!todo) return;
    var toggle = li.querySelector('.toggle');
    if (toggle) toggle.checked = todo.completed;
    if (todo.completed) {
      li.classList.add('completed');
    } else {
      li.classList.remove('completed');
    }
    /* update visibility under active/completed filters without full re-render */
    var isVisible = this.filter === 'all' ||
      (this.filter === 'active' && !todo.completed) ||
      (this.filter === 'completed' && todo.completed);
    li.style.display = isVisible ? '' : 'none';
  };

  TodoApp.prototype._updateAllTodoListItems = function () {
    var self = this;
    var items = document.querySelectorAll('.todo-list li');
    items.forEach(function (li) {
      var id = Number(li.dataset.id);
      var todo = self.todos.find(function (t) { return t.id === id; });
      if (todo) {
        var toggle = li.querySelector('.toggle');
        if (toggle) toggle.checked = todo.completed;
        if (todo.completed) {
          li.classList.add('completed');
        } else {
          li.classList.remove('completed');
        }
        var isVisible = self.filter === 'all' ||
          (self.filter === 'active' && !todo.completed) ||
          (self.filter === 'completed' && todo.completed);
        li.style.display = isVisible ? '' : 'none';
      }
    });
  };

  /**
   * @planks("the main section is hidden")
   * @planks("the footer is hidden")
   */
  TodoApp.prototype.render = function () {
    var main = document.querySelector('.main');
    var footer = document.querySelector('.footer');
    var todoList = document.querySelector('.todo-list');

    if (this.todos.length === 0) {
      main.style.display = 'none';
      footer.style.display = 'none';
    } else {
      main.style.display = '';
      footer.style.display = '';
    }

    this.renderTodoList();
    this.renderCounter();
    this.renderToggleAll();
    this.renderClearCompleted();
    this.renderFilters();
  };

  /**
   * @planks("{string} is added to the todo list")
   * @planks("{string} enters editing mode")
   * @planks("the edit input is focused with value {string}")
   */
  TodoApp.prototype.renderTodoList = function () {
    var self = this;
    var todoList = document.querySelector('.todo-list');
    todoList.innerHTML = '';

    var visible = this.getVisibleTodos();

    this.todos.forEach(function (todo) {
      var isVisible = visible.indexOf(todo) !== -1;
      var li = document.createElement('li');
      li.dataset.id = String(todo.id);
      if (todo.completed) li.classList.add('completed');
      if (self.editingId === todo.id) li.classList.add('editing');
      if (!isVisible) li.style.display = 'none';

      var view = document.createElement('div');
      view.className = 'view';

      var toggle = document.createElement('input');
      toggle.className = 'toggle';
      toggle.type = 'checkbox';
      toggle.checked = todo.completed;

      var label = document.createElement('label');
      label.textContent = todo.title;

      var destroy = document.createElement('button');
      destroy.className = 'destroy';

      view.appendChild(toggle);
      view.appendChild(label);
      view.appendChild(destroy);

      var edit = document.createElement('input');
      edit.className = 'edit';
      edit.value = todo.title;

      li.appendChild(view);
      li.appendChild(edit);
      todoList.appendChild(li);
    });

    if (self.editingId !== null) {
      var el = todoList.querySelector('li.editing .edit');
      if (el) el.focus();
    }
  };

  /**
   * @planks("the counter shows {string}")
   */
  TodoApp.prototype.renderCounter = function () {
    var counter = document.querySelector('.todo-count');
    var active = this.todos.filter(function (t) { return !t.completed; }).length;
    var word = active === 1 ? 'item' : 'items';
    counter.innerHTML = '<strong>' + active + '</strong> ' + word + ' left';
  };

  /**
   * @planks("the toggle-all checkbox is checked")
   * @planks("the toggle-all checkbox is unchecked")
   */
  TodoApp.prototype.renderToggleAll = function () {
    var toggleAll = document.querySelector('.toggle-all');
    var allCompleted = this.todos.length > 0 &&
      this.todos.every(function (t) { return t.completed; });
    toggleAll.checked = allCompleted;
  };

  /**
   * @planks("the clear completed button is hidden")
   */
  TodoApp.prototype.renderClearCompleted = function () {
    var btn = document.querySelector('.clear-completed');
    if (this.todos.some(function (t) { return t.completed; })) {
      btn.style.display = '';
    } else {
      btn.style.display = 'none';
    }
  };

  /**
   * @planks("the {string} filter link has the class {string}")
   */
  TodoApp.prototype.renderFilters = function () {
    var self = this;
    var filterMap = { all: '#/', active: '#/active', completed: '#/completed' };
    var expected = filterMap[self.filter] || '#/';
    document.querySelectorAll('.filters a').forEach(function (a) {
      if (a.getAttribute('href') === expected) {
        a.classList.add('selected');
      } else {
        a.classList.remove('selected');
      }
    });
  };

  /**
   * @planks("I navigate to {string}")
   * @planks("the page is reloaded")
   */
  TodoApp.prototype.handleRoute = function () {
    var hash = location.hash || '#/';
    if (hash === '#/active') this.filter = 'active';
    else if (hash === '#/completed') this.filter = 'completed';
    else this.filter = 'all';
    this.renderFilters();
  };

  /**
   * @planks("{string} is hidden")
   * @planks("all todos are visible")
   */
  TodoApp.prototype.getVisibleTodos = function () {
    if (this.filter === 'active') return this.todos.filter(function (t) { return !t.completed; });
    if (this.filter === 'completed') return this.todos.filter(function (t) { return t.completed; });
    return this.todos.slice();
  };

  /**
   * @planks("the page is open")
   * @planks("I type {string} in the new todo input")
   * @planks("I press Enter")
   * @planks("I check the toggle-all checkbox")
   * @planks("I click the toggle checkbox for {string}")
   * @planks("I click the destroy button for {string}")
   * @planks("I double-click the label of {string}")
   * @planks("I press Escape")
   * @planks("I blur the edit input")
   * @planks("I clear the edit input and type {string}")
   * @planks("I click the clear completed button")
   */
  TodoApp.prototype.bindEvents = function () {
    var self = this;

    window.addEventListener('hashchange', function () {
      self.handleRoute();
      self.render();
    });

    var newTodo = document.querySelector('.new-todo');
    newTodo.addEventListener('keydown', function (e) {
      if (e.key === 'Enter') {
        var val = newTodo.value.trim();
        if (val) {
          self.addTodo(val);
          newTodo.value = '';
        }
      }
    });

    var toggleAll = document.querySelector('.toggle-all');
    toggleAll.addEventListener('change', function () {
      self.toggleAll(toggleAll.checked);
    });

    var todoList = document.querySelector('.todo-list');

    todoList.addEventListener('click', function (e) {
      if (e.target.classList.contains('destroy')) {
        var li = e.target.closest('li');
        self.destroyTodo(Number(li.dataset.id));
      }
    });

    todoList.addEventListener('change', function (e) {
      if (e.target.classList.contains('toggle')) {
        var li = e.target.closest('li');
        var id = Number(li.dataset.id);
        var todo = self.todos.find(function (t) { return t.id === id; });
        if (todo) {
          todo.completed = e.target.checked;
          self.save();
          self._updateTodoListItem(id);
          self.renderCounter();
          self.renderToggleAll();
          self.renderClearCompleted();
        }
      }
    });

    todoList.addEventListener('dblclick', function (e) {
      if (e.target.tagName === 'LABEL') {
        var li = e.target.closest('li');
        self.editingId = Number(li.dataset.id);
        self._editCancelled = false;
        self.render();
      }
    });

    todoList.addEventListener('keydown', function (e) {
      if (e.target.classList.contains('edit')) {
        if (e.key === 'Enter') {
          var li = e.target.closest('li');
          self.editTodo(Number(li.dataset.id), e.target.value);
        }
        if (e.key === 'Escape') {
          var li = e.target.closest('li');
          var todo = self.todos.find(function (t) { return t.id === Number(li.dataset.id); });
          if (todo) e.target.value = todo.title;
          self._editCancelled = true;
          self.editingId = null;
          e.target.blur();
        }
      }
    });

    todoList.addEventListener('focusout', function (e) {
      if (e.target.classList.contains('edit')) {
        if (self._editCancelled) {
          self._editCancelled = false;
          self.render();
          return;
        }
        if (self.editingId !== null) {
          var li = e.target.closest('li');
          self.editTodo(Number(li.dataset.id), e.target.value);
        }
      }
    });

    var clearBtn = document.querySelector('.clear-completed');
    clearBtn.addEventListener('click', function () {
      self.clearCompleted();
    });
  };

  /**
   * @planks-provisional("features/app-infrastructure.feature:TodoApp exposes itself as a window global on startup")
   */
  window.App = TodoApp;
  window.app = new TodoApp();
})();

